declare module 'global' {
    interface EasyPieChartAnimate {
        duration?: number;
        enabled?: boolean;
    }
    interface EasyPieChartOptions {
        numberValue?: number;
        barColor?: string;
        barAlpha?: number;
        trackColor?: string | false;
        trackAlpha?: number;
        scaleColor?: string | false;
        scaleLength?: number;
        lineCap?: string;
        lineWidth?: number;
        size?: number;
        rotate?: number;
        render?: boolean;
        animate?: boolean | EasyPieChartAnimate;
        easing?: (x: number, t: number, b: number, c: number, d: number) => number;
        onStart?: (from: number, to: number) => void;
        onStep?: (from: number, to: number, currentValue: number) => void;
        onStop: (from: number, to: number) => void;
    }
    interface EasyPieChart {
        update(newValue: number | string): JQuery;
        forceUpdate(newValue?: number | string): JQuery;
        triggerAnimation(): JQuery;
        disableAnimation(): JQuery;
        enableAnimation(): JQuery;
        getCurrentValue(): number;
        options: EasyPieChartOptions;
        el: HTMLElement;
    }
    interface JQuery {
        easyPieChart(options: EasyPieChartOptions): JQuery;
        data(key: 'easyPieChart'): EasyPieChart;
    }
}
